// Human-readable, evidence-scoped assessment; scores are not generated by export checks.
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const root='/Users/zhengwei/Downloads/caption-v2-three-scenes-20260929';
const read=async name=>JSON.parse(await fs.readFile(root+'/'+name,'utf8'));
const api=async(path,body)=>{const r=await fetch('http://127.0.0.1:3000/api/footage/templates'+path,{method:body?'POST':'GET',headers:{'content-type':'application/json','x-requested-with':'moirai-footage'},body:body?JSON.stringify(body):undefined});const d=await r.json();assert.ok(r.ok,JSON.stringify(d));return d;};
const application=await read('application.json'),style=await read('style.json'),submission=await read('submission.json');
assert.deepEqual((await api('/dynamic-assets/'+style.id)).definition,style);
const item=await api('/production/'+submission.id+'/items/0');assert.equal(item.previews.length,3);
for(const p of item.previews)assert.equal(createHash('sha256').update(await fs.readFile(root+`/preview-${p.fixture}.mp4`)).digest('hex'),p.sha256);
const boundary=await read('boundary-manifest.json');
assert.equal(boundary.inspected,true);assert.equal(boundary.records.length,34);
assert.equal(style.revision,2);
const inspection='实际查看三个英文实拍的全部17句中点；17个合并边界图覆盖每句入场及退场，各12帧、30fps、下方1280×240裁切。117词高亮范围与实测时间另经校验。此前工作台已验证同一保存v2外观及位置/内容刷新恢复；本轮未重复所有编辑控件。';
const limitations='未试听、未实时整片播放。三个短横屏英语片段，不能代表中文实拍、竖屏、任意背景或主体位置。连续检查是局部裁切；联系表末尾超出源时长的填充格不作为实际视频帧。原生阅读速度与整句预算警告仍保留。';
const request={application,review:{templateId:item.templateId,templateRevision:item.templateRevision,batchId:submission.id,item:0,reviewer:'Codex · 无底板逐词字幕v2应用评审',
composition:{score:22,rationale:'取消底板减少矩形遮挡，居中下方单/双行可辨；文字仍压到部分手势，未实现任意主体构图适配。'},
motion:{score:22,rationale:'117词对齐校验通过，全部17句边界裁切未发现高亮导致跳行或退出残留。入场位移克制，换句直接切换，动态精致度仍有限；未试听。'},
assets:{score:17,rationale:'3px描边和轻阴影使浅衣、深衣上的白字及黄色当前词可辨。花纹背景仍竞争视觉，基础字体和配色不足以证明开拍同等质感。'},
adaptation:{score:16,rationale:'同一v2覆盖三段实拍17句及单/双行。全是英语横屏短片，手势遮挡与内容阅读速度仍待处理；未验证中文干净实拍或竖屏。'},
editability:{score:9,rationale:'保存v2的原生应用直接生产，文字/高亮可编辑，样式与词时间分离。既有真实浏览器验证底色关闭、描边3、阴影.7及应用内容位置刷新恢复，本輪内容导入验证也通过。'},
evidence:item.previews.map(p=>({fixture:p.fixture,sha256:p.sha256})),inspection,limitations,blockingFindings:['文字仍覆盖部分手势，复杂花纹背景的分离度及基础动态设计需继续打磨。','未完成试听、中文实拍及更多画幅适配验收；阅读速度和句预算警告未消除。'],listened:false}};
await fs.writeFile(root+'/style-review-request.json',JSON.stringify(request,null,2));
const receipt=await api('/dynamic-assets/reviews',request);assert.equal(receipt.total,86);assert.equal(receipt.meetsInternalThreshold,false);
const current=(await api('/dynamic-assets/reviews')).reviews.find(r=>r.id===receipt.id);assert.ok(current.current&&current.evidenceCurrent);
await fs.writeFile(root+'/style-review-receipt.json',JSON.stringify(current,null,2));
const doc=await read('inspection.json');Object.assign(doc,{inspection,limitations,score:86,reviewId:receipt.id,listened:false});await fs.writeFile(root+'/inspection.json',JSON.stringify(doc,null,2));
console.log(JSON.stringify({id:receipt.id,total:receipt.total,current:current.current,evidenceCurrent:current.evidenceCurrent}));
